from AlgorithmImports import *
from datetime import datetime, timedelta, time
from collections import deque


class SpyFiveMinuteCallStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute, dataNormalizationMode=DataNormalizationMode.Raw).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda u: u.IncludeWeeklys()
                       .Strikes(-200, 200)
                       .Expiration(0, 365)
        )
        self.option_symbol = self.option.Symbol

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket_end = None
        self.bucket_bars = []
        self.last_minute_end = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_date = None
        self.no_entry_today = False

    def OnData(self, slice: Slice):
        local_time = self.Time

        # Never intentionally carry an option into expiration.
        if self.held_option is not None and self.expiration_date is not None:
            if local_time.date() >= self.expiration_date:
                self.no_entry_today = True
                if self.exit_ticket is None:
                    self.Debug(f"{local_time}: expiration liquidation for {self.held_option}")
                    self.exit_ticket = self.Liquidate(self.held_option)

        # Immediately liquidate unexpected SPY exercise/assignment holdings.
        if self.Portfolio[self.spy].Invested:
            self.Debug(f"{local_time}: unexpected SPY exercise/assignment; liquidating equity")
            self.Liquidate(self.spy)
            self.no_entry_today = True

        if self.spy not in slice.Bars:
            return

        minute_bar = slice.Bars[self.spy]
        bar_end = minute_bar.EndTime.astimezone(self.TimeZone).replace(tzinfo=None)

        if not self._is_regular_session(bar_end):
            return

        bucket_end = self._bucket_end(bar_end)

        if self.current_bucket_end is None:
            self.current_bucket_end = bucket_end
        elif bucket_end != self.current_bucket_end:
            self._finish_bucket(slice, minute_bar.Close)
            self.current_bucket_end = bucket_end
            self.bucket_bars = []

        # Reject a bucket containing a missing minute.
        if self.last_minute_end is not None:
            expected = self.last_minute_end + timedelta(minutes=1)
            if bar_end != expected:
                self.bucket_bars = []

        self.bucket_bars.append(minute_bar)
        self.last_minute_end = bar_end

        if len(self.bucket_bars) == 5 and bar_end == self.current_bucket_end:
            self._finish_bucket(slice, minute_bar.Close)
            self.bucket_bars = []

    def _finish_bucket(self, slice: Slice, current_spy_price: float):
        if len(self.bucket_bars) != 5 or self.current_bucket_end is None:
            return

        closes = [float(x.Close) for x in self.bucket_bars]
        close = closes[-1]

        self.fast_values.append(close)
        self.slow_values.append(close)

        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            return

        fast = sum(list(self.fast_values)[-5:]) / 5.0
        slow = sum(self.slow_values) / 20.0

        crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        end_time = self.current_bucket_end.time()
        eligible_time = time(9, 45) <= end_time <= time(14, 30)

        if crossover and eligible_time:
            self._try_entry(slice, current_spy_price)

    def _try_entry(self, slice: Slice, spy_price: float):
        if self.no_entry_today:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        chains = list(slice.OptionChains)
        if not chains:
            self.Debug(f"{self.Time}: skipped entry; no option chain")
            return

        today = self.Time.date()
        expirations = sorted({
            contract.Expiry.date()
            for chain in chains
            for contract in chain
            if contract.Expiry.date() >= today
        })

        if not expirations:
            self.Debug(f"{self.Time}: skipped entry; no valid expiration")
            return

        expiration = expirations[0]
        minimum_strike = 1.01 * float(spy_price)

        candidates = []
        for chain in chains:
            for contract in chain:
                if (
                    contract.Symbol.ID.OptionStyle == OptionStyle.American
                    and contract.Symbol.ID.OptionRight == OptionRight.Call
                    and contract.Expiry.date() == expiration
                    and float(contract.Strike) >= minimum_strike
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug(f"{self.Time}: skipped entry; no qualifying call")
            return

        candidates.sort(key=lambda c: (float(c.Strike), str(c.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(f"{self.Time}: submitted call entry {selected.Symbol}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
                self.held_option = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.expiration_date = order_event.Symbol.ID.Date.date()
                self.Debug(
                    f"{self.Time}: entered {self.held_option}, "
                    f"fill={self.entry_price:.4f}"
                )

            elif self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
                self.Debug(f"{self.Time}: exited {order_event.Symbol}")
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
                self.expiration_date = None

        if hasattr(order_event, "IsAssignment") and order_event.IsAssignment:
            self.Debug(f"{self.Time}: unexpected option exercise/assignment")
            self.no_entry_today = True
            if self.Portfolio[self.spy].Invested:
                self.Liquidate(self.spy)

    def OnEndOfDay(self, symbol):
        if symbol != self.spy:
            return

        self.no_entry_today = False

        if self.held_option is None or self.expiration_date is None:
            return

        if self.expiration_date - self.Time.date() == timedelta(days=1):
            if self.exit_ticket is None:
                self.Debug(f"{self.Time}: time-stop liquidation for {self.held_option}")
                self.exit_ticket = self.Liquidate(self.held_option)

    def OnSecuritiesChanged(self, changes):
        pass

    def _try_exit(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_ticket is not None:
            return

        security = slice.Bars.get(self.held_option)
        if security is None:
            return

        bid = self.Securities[self.held_option].BidPrice
        ask = self.Securities[self.held_option].AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self.Debug(f"{self.Time}: profit target reached for {self.held_option}")
            self.exit_ticket = self.Liquidate(self.held_option)

    def _is_regular_session(self, t):
        return time(9, 30) <= t.time() <= time(16, 0)

    def _bucket_end(self, t):
        minutes = (t.hour * 60 + t.minute) - (9 * 60 + 30)
        end_minutes = 9 * 60 + 35 + (minutes // 5) * 5
        return datetime.combine(t.date(), time(0, 0)) + timedelta(minutes=end_minutes)

